```cpp
class Base {
 public:
  virtual void print() {
    std::cout << "Base";
  }
};
class Derived : public Base {
 public:
  void print() override {
    std::cout << "Derived";
  }
};
void show(Base b) {
  b.print();
}
int main() {
  Derived d;

  show(d);  // In ra "Base" thay vì "Derived"
}
```

